INSERT OR REPLACE INTO p_studio_batch (id, act_id, num, br_batch_id, name, brief_json, setup_json, plan_json, status) VALUES ('98d6ab10d32e7a8ea94e19b3', 'brand_bonk_golf', NULL, NULL, 'Early Black Friday: offer-free statics (real photos only)', '{"angle": "Early Black Friday, offer-free lines: gift-giver and product heroes that run before and alongside the warm-up offer.", "why": "235 B (gift-giver line on a plain studio hero) is the account anchor at 1.57x TW, 280 orders in 60 days; in BFCM 2025 the evergreen heroes beat every offer ad.", "concept": "Real bonkgolf.com studio photos only (Floyd: no AI imagery, ever). Every line already has its finished image. Offer lines 12 to 15 wait for Floyd.", "post_copy": "The golf hat with the ball marker and tees built in. Magnet in the bill, tee slots in the side, matching marker in the box.", "testing": "concepts", "lines": [{"text": "ebf-01: Retire his old cap. Gift-giver line from 235 B (the account anchor) on a fresh Dunes Day studio hero. Testing: the winning line in gift season.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f8b21d8aeb112252cd701d6e.png"}, {"text": "ebf-02: Skip the golf-themed gift. Get the hat he''ll wear every round. Smoke Show hero. Testing: usefulness vs nostalgia (01).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0e18de35ce85c293fded2c98.png"}, {"text": "ebf-03: Built in. Not bolted on. Twilight + 3 callouts (magnet holds marker, tee slots, matching marker in the box). Testing: callouts vs single line.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e4430462e64a7234d16e1cfc.png"}, {"text": "ebf-04: Review over product: \"My husband loved how his tees have a place other than his ears.\" (Judge.me 5 stars, Pin Raider).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c42fa4878660eefed96e4a0b.png"}, {"text": "ebf-05: Review over product: \"Man coolest golf hat ever made!\" (Judge.me 5 stars, Viper). Testing: style proof vs function proof (04).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/4d315f070bca12b404ad7c16.png"}, {"text": "ebf-06: Stop fumbling. Start playing. (225 B line, self-buyer) on Smoke Show three-quarter hero.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7ecf85d51b8598e365fe0e04.png"}, {"text": "ebf-07: Black goes with every bag. Twilight, Viper, Pin Raider three-up. Testing: three blacks vs one hero.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e009232903f3a7d1e7c70830.png"}, {"text": "ebf-08: Built for lefties. Finally. Southpaw Snapback photo only. Testing: lefty audience.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0513a75f1cb42e6f0ae94b63.png"}, {"text": "ebf-09: Review over product: ponytail through 1 of 3 locations (Judge.me 5 stars, Clean Open Back). Testing: women.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3812876ad5ed1a1a8db0af4c.png"}, {"text": "ebf-10: YOUTH SIZE. Make the junior golfer feel legit. Youth Smoke Show. Testing: youth gifter; says youth big because Youth vs Standard is the top refund.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/52ed0c84e1602217a144f953.png"}, {"text": "ebf-11: HOLD until Floyd confirms list-first: New holiday bundles. The list sees them first. Join the list. Smoke Show gift set photo, no price.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/a446947ce3feb9819fcfa2dc.png"}], "source": "Bonk BFCM ads chat, 2026-10-13 (docs/bfcm-bonk-concepts.md, Batch 1 lines 1 to 11)", "reference": "docs/bfcm-bonk-concepts.md"}', '{"products": [], "images": ["https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f8b21d8aeb112252cd701d6e.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0e18de35ce85c293fded2c98.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e4430462e64a7234d16e1cfc.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c42fa4878660eefed96e4a0b.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/4d315f070bca12b404ad7c16.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7ecf85d51b8598e365fe0e04.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e009232903f3a7d1e7c70830.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0513a75f1cb42e6f0ae94b63.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3812876ad5ed1a1a8db0af4c.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/52ed0c84e1602217a144f953.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/a446947ce3feb9819fcfa2dc.png"], "swipe": []}', NULL, 'draft');
